import * as React from "react"
import { useState, useRef, useEffect } from "react"
import { addPropertyControls, ControlType } from "framer"
// Rolling digits with motion blur. `?external=react` makes esm.sh reuse
// Framer's React instance rather than bundling a second copy (two Reacts on a
// page breaks hooks). The library's stylesheet is inlined below as ROLLING_CSS,
// so nothing else is fetched at runtime.
// @ts-ignore
import { RollingNumber } from "@kitlangton/rolling-number/react"

// ---- Motion tokens ----
const EASE = "cubic-bezier(0.22, 1, 0.36, 1)" // all standard transitions
const POP = "cubic-bezier(0.35, 1.55, 0.65, 1)" // overshoot, for pop-ins

// Poof burst that SETTLES into a faded, still-visible label (the token stays
// on the card in light gray after being swept, per the design).
// ---- @kitlangton/rolling-number stylesheet (inlined, v0.4.1) ----
const ROLLING_CSS = `
.rn-root {
  display: inline-block;
  position: relative;
  white-space: pre;
  unicode-bidi: isolate;
  vertical-align: baseline;
}
.rn-root > .rn-measure,
.rn-root > .rn-visual { display: none; }
.rn-root[data-rn-measuring] > .rn-measure {
  display: inline-flex;
  position: relative;
  visibility: hidden;
  white-space: pre;
  padding: 0;
  border: 0;
}
.rn-token { display: inline-block; padding: 0; border: 0; }
.rn-root[data-rn-measuring] > .rn-value,
.rn-react[data-rn-hydrated] > .rn-semantic,
.rn-solid[data-rn-hydrated] > .rn-semantic {
  position: absolute;
  inset: 0;
  padding: 0;
  margin: 0;
  color: transparent;
  z-index: 1;
}
/* A single native text layer is selectable; decorative reels never enter a copy. */
.rn-value::selection, .rn-semantic::selection {
  color: HighlightText;
  background: Highlight;
}
.rn-root[data-rn-ready] > .rn-visual {
  display: block;
  position: absolute;
  inset: 0;
  pointer-events: none;
  user-select: none;
}
.rn-slot {
  position: absolute;
  left: 0;
  overflow: hidden;
  /* Space for italic overhang without changing the measured advance width. */
  box-sizing: content-box;
  padding-inline: 0.15em;
  margin-inline-start: -0.15em;
  -webkit-mask-image: var(--rn-mask, linear-gradient(
    to bottom,
    transparent,
    #000 var(--rn-edge-fade, 0.12em),
    #000 calc(100% - var(--rn-edge-fade, 0.12em)),
    transparent
  ));
  mask-image: var(--rn-mask, linear-gradient(
    to bottom,
    transparent,
    #000 var(--rn-edge-fade, 0.12em),
    #000 calc(100% - var(--rn-edge-fade, 0.12em)),
    transparent
  ));
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}
@supports (overflow: clip) {
  .rn-slot { overflow-x: visible; overflow-y: clip; }
}
.rn-slot:not([data-rn-wheel]) {
  overflow: visible;
  -webkit-mask-image: none;
  mask-image: none;
}
.rn-enter, .rn-reel, .rn-face { display: block; }
.rn-reel { position: relative; }
.rn-ink { display: block; position: absolute; inset: 0; will-change: transform; }
/* Safari's SVG filter must rasterize the smear's descendants into its input. */
.rn-smear .rn-ink { will-change: auto; }
/* Each turning half carries its own perspective transform, not a shared 3D scene. */
/* The slot acts as the bezel: the card stays vertically framed while it hinges. */
.rn-slot[data-rn-flap] { -webkit-mask-image: none; mask-image: none; }
/* Hinged faces must occlude the cards behind them, including with default CSS. */
:where(.rn-slot[data-rn-flap]) .rn-face { background: var(--rn-flap-background, Canvas); }
.rn-flap { position: absolute; inset: 0; transform-origin: 50% 50%; backface-visibility: hidden; }
/* --rn-crease is the visible hinge gap between the two halves. */
.rn-flap-top { clip-path: inset(0 0 calc(50% + var(--rn-crease, 1px) / 2) 0); }
.rn-flap-bottom { clip-path: inset(calc(50% + var(--rn-crease, 1px) / 2) 0 0 0); }
.rn-sharp, .rn-smear { display: block; }
.rn-smear { position: absolute; inset: 0; pointer-events: none; }
.rn-blur-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.rn-face { text-align: center; white-space: pre; }
.rn-react, .rn-solid { display: inline-block; position: relative; white-space: pre; unicode-bidi: isolate; }
.rn-mount { display: inline-block; user-select: none; }
.rn-mount .rn-value { pointer-events: none; }
.rn-react:not([data-rn-hydrated]) > .rn-mount,
.rn-solid:not([data-rn-hydrated]) > .rn-mount { display: none; }
`

const KEYFRAMES_CSS = `
/* No visible focus indicator on the control, by request: both a ring around
   the bar and one around the knob read as a selected form field. This rule
   still has to exist - without it the browser draws its own default ring on
   keyboard focus, which is louder than either. The control stays fully
   keyboard-operable; only the indicator is gone. */
.cdc-track:focus-visible {
  outline: none;
}

@keyframes poofSettle {
  0%   { transform: translateX(-50%) translateY(0) scale(1); filter: blur(0px); opacity: 1; }
  45%  { transform: translateX(-50%) translateY(-6px) scale(1.45); filter: blur(3px); opacity: 0.12; }
  /* Lands on the element's own resting opacity. Hardcoding a value here
     means the label snaps the instant the animation is removed, because this
     animation does not hold its final frame. */
  100% { transform: translateX(-50%) translateY(0) scale(1); filter: blur(0px); opacity: var(--label-swept); }
}
/* a dust mote that POPS out (fast scale-up) then drifts and fades.
   distance/direction/timing set inline via CSS variables */
@keyframes dustDrift {
  0%   { transform: translate(-50%, -50%) translate(0, 0) scale(0.4); opacity: 0; }
  14%  { transform: translate(-50%, -50%) translate(calc(var(--dx) * 0.16), calc(var(--dy) * 0.16)) scale(1); opacity: var(--o, 0.9); }
  100% { transform: translate(-50%, -50%) translate(var(--dx), var(--dy)) scale(0.5); opacity: 0; }
}
/* the label itself dissolves as the motes scatter */
@keyframes labelDissolve {
  0%   { opacity: 1; filter: blur(0px); transform: translateX(-50%) scale(1); }
  100% { opacity: 0; filter: blur(4px); transform: translateX(-50%) scale(1.1); }
}
/* the mark itself: the disc pops in past its size, then the tick draws.
   11 is the path's length, rounded up from 10.64. */
@keyframes checkPop {
  0%   { transform: scale(0.3); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}
@keyframes checkDraw {
  from { stroke-dashoffset: 11; }
  to   { stroke-dashoffset: 0; }
}
/* a lighter-green highlight sweeps across the SOL text, left to right,
   entering from off the left and exiting off the right */
/* completion flourishes on the fill */
@keyframes fillShine {
  0%   { transform: translateX(-100%); opacity: 0; }
  12%  { opacity: 1; }
  100% { transform: translateX(220%); opacity: 1; }
}
@keyframes fillFlood {
  0%   { transform: translateX(100%); }
  100% { transform: translateX(0%); }
}
@keyframes fillPulse {
  0%   { opacity: 0; }
  30%  { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes solShimmer {
  0%   { background-position: 240% 0; }
  100% { background-position: -140% 0; }
}
/* constant shimmer - travels exactly one tile (180px) per loop so every
   cycle is identical and seamless (percent-based looping was inconsistent) */
@keyframes hintShimmer {
  0%   { background-position: -180px 0; }
  100% { background-position: 0px 0; }
}
`

// ---- Reduced motion ----
// Gentler, not absent: opacity and colour transitions stay (they still hide
// seams), while travel, scale, stagger, motion blur and the looping shimmers
// come off. Handled in JS rather than CSS because the digit reels' motion blur
// and the dust motes are props, not stylesheet rules.
function usePrefersReducedMotion(): boolean {
    const [reduced, setReduced] = useState(false)
    useEffect(() => {
        const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
        const sync = () => setReduced(mq.matches)
        sync()
        mq.addEventListener("change", sync)
        return () => mq.removeEventListener("change", sync)
    }, [])
    return reduced
}

