const waypointX = (i: number, w: number) => w * ((i + 0.5) / TOKENS.length)

// The waypoint columns are absolutely positioned, so they cannot size their
// row. Its height is set to exactly what one column needs - dot, gap, one line
// of label - instead of a round 40px that left 18px of dead space under the
// labels on top of the card's own padding.
const WAYPOINT_DOT = 3
const WAYPOINT_GAP = 6
const WAYPOINT_LINE = 13 // the label's line box; pinned so the sum is exact
const WAYPOINT_ROW_H = WAYPOINT_DOT + WAYPOINT_GAP + WAYPOINT_LINE // 22

// ---- Rolling digit timing ----
const ROLL_MS = 700 // passed to the library as `duration`
const SOL_SHIMMER_MS = 1500 // highlight sweep across the SOL pill
const SOL_SHIMMER_FADE = 0.9 // how strongly the sweep reads over the pill
const HINT_FADE = 0.7 // how much colour the track hint's shimmer carries

// ---- Rolling numbers (@kitlangton/rolling-number, motion blur on) ----
// The library owns the digit reels: interruptible rolls, native number
// formatting, and opt-in vertical motion blur while the reel is in flight.

function RollingPrice({
    value,
    color,
    motionBlur = true,
}: {
    value: number
    color: string
    motionBlur?: boolean
}) {
    return (
        <RollingNumber
            value={value}
            locales="en-US"
            format={{ style: "currency", currency: "USD" }}
            duration={ROLL_MS}
            motionBlur={motionBlur}
            style={{
                fontSize: PRICE_SIZE,
                lineHeight: 1,
                fontWeight: 500,
                color,
                fontVariantNumeric: "tabular-nums",
            }}
        />
    )
}

// SOL gain - same engine, green, with a static SOL suffix.
// signDisplay keeps the leading "+", and 3 fixed decimals keep "0.064" stable.
function RollingSolGain({
    value,
    color,
    size = PRICE_SIZE,
    suffix = "SOL",
    suffixScale = 0.5,
    motionBlur = true,
    rollMs = SOL_ROLL_MS,
    stagger = SOL_STAGGER,
    shimmer = false,
    shimmerMs = SOL_SHIMMER_MS,
    shimmerFade = SOL_SHIMMER_FADE,
    shimmerColor = "#FFFFFF",
    shimmerBlend = "screen",
}: {
    value: number
    color: string
    size?: number
    /** Unit trailing the number. Empty when the label already carries it. */
    suffix?: string
    suffixScale?: number
    motionBlur?: boolean
    rollMs?: number
    stagger?: Stagger
    shimmer?: boolean
    shimmerMs?: number
    shimmerFade?: number
    shimmerColor?: string
    shimmerBlend?: string
}) {
    const suffixStyle: React.CSSProperties = {
        fontSize: size * suffixScale,
        marginLeft: size * 0.28,
    }
    return (
        <span
            style={{
                position: "relative",
                display: "inline-flex",
                alignItems: "center",
                fontSize: size,
                lineHeight: 1,
                fontWeight: 500,
                color,
            }}
        >
            <RollingNumber
                value={value}
                locales="en-US"
                format={{
                    signDisplay: "always",
                    minimumFractionDigits: 3,
                    maximumFractionDigits: 3,
                }}
                duration={rollMs}
                stagger={stagger}
                motionBlur={motionBlur}
                style={{ fontVariantNumeric: "tabular-nums" }}
            />
            {suffix && <span style={suffixStyle}>{suffix}</span>}
            {/* The highlight rides a static copy of the settled value, clipped to
          its own glyphs, so the sweep brightens the text and nothing behind
          it. It has to be a plain span: the reel's own layers are absolutely
          positioned and contribute nothing to a background-clip:text. Living
          in here means it inherits `size` and can never drift from the reel. */}
            {shimmer && (
                <span
                    aria-hidden="true"
                    style={{
                        position: "absolute",
                        inset: 0,
                        display: "inline-flex",
                        alignItems: "center",
                        fontSize: size,
                        lineHeight: 1,
                        fontWeight: 500,
                        fontVariantNumeric: "tabular-nums",
                        pointerEvents: "none",
                        backgroundImage: `linear-gradient(105deg, transparent 20%, ${shimmerColor} 50%, transparent 80%)`,
                        backgroundSize: "250% 100%",
                        backgroundRepeat: "no-repeat",
                        WebkitBackgroundClip: "text",
                        backgroundClip: "text",
                        color: "transparent",
                        WebkitTextFillColor: "transparent",
                        mixBlendMode:
                            shimmerBlend as React.CSSProperties["mixBlendMode"],
                        opacity: shimmerFade,
                        // Held until the reel has landed. This layer paints the settled
                        // value, so starting it mid-roll would sweep a figure the reel is
                        // not showing yet. Derived, so the two cannot drift apart - and it
                        // has to allow for the stagger: the library spends up to a third
                        // of the roll cascading the digits, so the last one lands after
                        // `rollMs` rather than at it.
                        animation: `solShimmer ${shimmerMs}ms ${EASE} ${
                            solSettleMs(rollMs, stagger) + 120
                        }ms 1 both`,
                    }}
                >
                    {SOL_LABEL}
                    {suffix && <span style={suffixStyle}>{suffix}</span>}
                </span>
            )}
        </span>
    )
}

// ---- Dust burst ----
// A cluster of motes centered on a waypoint. When `go` flips true they POP
// outward radially and fade out. Deterministic per seed so it's stable.
// Particle defaults. The scales multiply the tuned spread of random values
// below rather than replacing it, so turning one up keeps the variety.
const MOTES = 34 // particles per waypoint
const DUST_COLOR = "#9E9E9E"
const DUST_SIZE = 0.6 // multiplier on each mote's diameter
const DUST_SPREAD = 2 // multiplier on how far they travel
const DUST_MS = 1300 // base flight time before the per-mote variance
const DUST_OPACITY = 1 // multiplier on each mote's starting opacity

function DustBurst({
    go,
    seed,
    x,
    color,
    count,
    sizeScale,
    spread,
    durationMs,
    opacityScale,
}: {
    go: boolean
    seed: number
    x: number
    color: string
    count: number
    sizeScale: number
    spread: number
    durationMs: number
    opacityScale: number
}) {
    const motes: React.ReactNode[] = []
    for (let m = 0; m < count; m++) {
        const rnd = (n: number) => {
            const v =
                Math.sin((seed + 1) * 12.9898 + (m + 1) * 78.233 + n * 3.71) *
                43758.5453
            return v - Math.floor(v) // 0..1
        }
        // Spaced around the full circle, so the ring stays even at any count.
        const angle = (m / count) * Math.PI * 2 + (rnd(0) - 0.5) * 0.7
        const dist = (12 + rnd(1) * 30) * spread
        const dx = Math.cos(angle) * dist
        const dy = Math.sin(angle) * dist - 5 * spread // slight upward bias
        const size = (1.4 + rnd(2) * 2.4) * sizeScale // fine, varied motes
        const dur = (durationMs / 1000) * (1 + rnd(3) * 0.423) // same ¬±42% spread
        const delay = rnd(4) * 0.14 // staggered
        const startO = Math.min(1, (0.65 + rnd(5) * 0.35) * opacityScale)
        motes.push(
            <span
                key={m}
                style={
                    {
                        position: "absolute",
                        left: 0,
                        top: 0,
                        width: size,
                        height: size,
                        borderRadius: "50%",
                        background: color,
                        opacity: 0,
                        "--dx": `${dx}px`,
                        "--dy": `${dy}px`,
                        "--o": startO,
                        animation: go
                            ? `dustDrift ${dur}s ${EASE} ${delay}s forwards`
                            : "none",
                        pointerEvents: "none",
                    } as React.CSSProperties
                }
            />
        )
    }
    return (
        <span
            style={{
                position: "absolute",
                left: x,
                top: 8, // roughly on the label's center
                width: 0,
                height: 0,
                pointerEvents: "none",
                zIndex: 2,
            }}
        >
            {motes}
        </span>
    )
}

// ---- Slider physics (tunable) ----
// No momentum: the knob only ever goes as far as the finger drags it. On
// release it returns home; dragging to the end triggers the sweep.
const COMPLETE_AT = 0.985 // drag past this (then release) triggers the sweep
// ---- Rubber banding (iOS-style) ----
// Past either end the knob keeps moving, but with diminishing returns, so the
// drag stays alive while telling you you've hit the boundary.
const RUBBER_DEAD = 0.022 // slack before any stretch - overshooting to 0/100% doesn't wobble
const RUBBER_MAX = 0.05 // asymptote: stretch can never exceed this, however hard you pull
// Diminishing returns: linear near zero, flattening toward RUBBER_MAX.
const rubberBand = (over: number) => (RUBBER_MAX * over) / (over + RUBBER_MAX)
const STRETCH = 0.5 // how much the track grows per unit of overshoot
const HOME_MS = 420 // return-to-start duration after releasing short of the goal

// ---- Main card ----
export interface ConvertDustCardProps {
    /** Card heading. */
    title?: string
    /** Dark surface (the default) or the light variant. */
    dark?: boolean
    /** Sheet grab handle above the title. */
    showGrabber?: boolean
    /** Token icons in the coin list. */
    showIcons?: boolean
    /** Slider fill: the colour the ramp peaks on before the end colour. */
    gradientMid?: string
    /** Slider fill: the colour the ramp finishes on. */
    gradientEnd?: string
    /** Light theme's slider fill mid colour. */
    gradientMidLight?: string
    /** Light theme's slider fill end colour. */
    gradientEndLight?: string
    /** Mid-colour stop position along the gradient line (Figma: 0.56). */
    gradientMidAt?: number
    /** End-colour stop position along the gradient line (Figma: 0.83). */
    gradientEndAt?: number
    /** Blur on the fill, in px. Softens any banding in the ramp. */
    gradientBlur?: number
    /** Fill of the confirmation checkmark. */
    checkColor?: string
    /** How long the SOL figure takes to roll into place, in ms. */
    solRollMs?: number
    /** Digits of travel on that roll. Higher spins further before settling. */
    solRollSpin?: number
    /** Order the SOL digits land in. "none" rolls them together. */
    solStagger?: Stagger
    /** Duration of the highlight sweep across the SOL figure, in ms. */
    solShimmerMs?: number
    /** How strongly that sweep reads, 0 to 1. */
    solShimmerFade?: number
    /** Colour in the track hint's shimmer, 0 to 1. 0 leaves the text plain. */
    hintFade?: number
    /** Dust particles: colour. */
    dustColor?: string
    /** Dust particles: how many burst from each waypoint. */
    dustCount?: number
    /** Dust particles: size multiplier. */
    dustSize?: number
    /** Dust particles: how far they travel. */
    dustSpread?: number
    /** Dust particles: flight time in ms. */
    dustMs?: number
    /** Dust particles: opacity multiplier. */
    dustOpacity?: number
    /** Flourish on the fill when the sweep completes. */
    completionFlourish?: Flourish
    /** How long that flourish runs, in ms. */
    flourishMs?: number
    /** Blur on the shine streak, in px. */
    shineBlur?: number
    /** Fires once the sweep completes. */
    onSwept?: () => void
    style?: React.CSSProperties
}

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight auto
 * @framerIntrinsicWidth 382
 * @framerIntrinsicHeight 373
 */
export default function ConvertDustCard({
    title = "Clean dust",
    dark = true,
    showGrabber = true,
    showIcons = false,
    gradientMid = GRAD_MID,
    gradientEnd = GRAD_END,
    gradientMidLight = GRAD_MID_LIGHT,
    gradientEndLight = GRAD_END_LIGHT,
    gradientMidAt = GRAD_MID_AT,
    gradientEndAt = GRAD_END_AT,
    gradientBlur = GRAD_BLUR,
    checkColor = GREEN,
    solRollMs = SOL_ROLL_MS,
    solRollSpin = SOL_SPIN,
    solStagger = SOL_STAGGER,
    solShimmerMs = SOL_SHIMMER_MS,
    solShimmerFade = SOL_SHIMMER_FADE,
    hintFade = HINT_FADE,
    dustColor = DUST_COLOR,
    dustCount = MOTES,
    dustSize = DUST_SIZE,
    dustSpread = DUST_SPREAD,
    dustMs = DUST_MS,
    dustOpacity = DUST_OPACITY,
    completionFlourish = FLOURISH,
    flourishMs = FLOURISH_MS,
    shineBlur = SHINE_BLUR,
    onSwept,
    style,
}: ConvertDustCardProps) {
    const T: Theme = dark ? DARK_THEME : LIGHT_THEME
    // Each theme has its own fill pair; everything that paints the fill's
    // colours (fill, hint shimmer, flood) reads these.
    const fillMid = dark ? gradientMid : gradientMidLight
    const fillEnd = dark ? gradientEnd : gradientEndLight
    const reduced = usePrefersReducedMotion()
    // The hint shimmer's colours, blended back toward the resting grey. 1 is the
    // full accent, 0 leaves the text plain grey with no shimmer to see.
    const hintTint = (c: string) =>
        `color-mix(in srgb, ${c}, ${T.hint} ${Math.round((1 - hintFade) * 100)}%)`
    // Kept as local aliases so the markup below reads the same as the prototype.
    const SHOW_PHONE = false
    const SHOW_GRABBER = showGrabber
    const SHOW_ICONS = showIcons

    // The card is fluid below its design width, so every position is derived
    // from the measured track rather than the constant. TRACK_W is the value
    // before first measurement and the ceiling.
    const [trackW, setTrackW] = useState(TRACK_W)
    const usable = usableFor(trackW)
    const [progress, setProgress] = useState(0)
    const [complete, setComplete] = useState(false)
    const [active, setActive] = useState(false) // fill fades in only while the handle is held
    const [solRoll, setSolRoll] = useState(false) // fires the SOL roll AFTER the block fades in, so every digit's roll is visible
    // The header chip reads "claimed" once the SOL figure has landed, so it
    // confirms the settled payoff rather than competing with it mid-roll.
    const [claimed, setClaimed] = useState(false)
    const claimableRef = useRef<HTMLSpanElement | null>(null)
    const claimedRef = useRef<HTMLSpanElement | null>(null)
    const [wordW, setWordW] = useState<{
        claimable: number
        claimed: number
    } | null>(null)
    const [loaded, setLoaded] = useState(false) // gates the load count-up
    const progressRef = useRef(0)
    const trackRef = useRef<HTMLDivElement | null>(null)
    const solHostRef = useRef<HTMLSpanElement | null>(null)
    const rectRef = useRef<DOMRect | null>(null) // track rect frozen at grab time (see rawFromEvent)
    const loadTimer = useRef<ReturnType<typeof setTimeout> | undefined>(
        undefined
    )
    const dragging = useRef(false)
    const raf = useRef(0)

    // Fire the completion state.
    const finish = () => {
        set(1)
        setComplete(true)
        onSwept?.()
    }

    useEffect(() => {
        if (!solRoll) {
            setClaimed(false)
            return
        }
        const t = setTimeout(
            () => setClaimed(true),
            reduced ? 0 : solSettleMs(solRollMs, solStagger)
        )
        return () => clearTimeout(t)
    }, [solRoll, solRollMs, solStagger, reduced])

    // "claimed" is shorter than "claimable", and the chip is right-aligned, so
    // swapping the text would snap its left edge. Measure both words once the
    // embedded face has loaded and animate between the two real widths.
    useEffect(() => {
        let live = true
        const measure = () => {
            if (!live || !claimableRef.current || !claimedRef.current) return
            setWordW({
                claimable: claimableRef.current.offsetWidth,
                claimed: claimedRef.current.offsetWidth,
            })
        }
        measure()
        if (typeof document !== "undefined" && document.fonts?.ready) {
            document.fonts.ready.then(measure)
        }
        return () => {
            live = false
        }
    }, [])

    // Count up to the total once, when the card appears (0 -> $4.78).
    useEffect(() => {
        const t = setTimeout(() => setLoaded(true), 250)
        return () => clearTimeout(t)
    }, [])

    useEffect(() => {
        const el = trackRef.current
        if (!el || typeof ResizeObserver === "undefined") return
        const ro = new ResizeObserver((entries) => {
            const w = entries[0]?.contentRect.width
            if (w && w > 0) setTrackW(w)
        })
        ro.observe(el)
        return () => ro.disconnect()
    }, [])

    // Stop the page from scrolling while dragging the knob. touch-action:none
    // covers most cases, but React's touch listeners are passive, so some
    // mobile browsers still scroll - a native non-passive listener that
    // prevents the default is the reliable fix.
    useEffect(() => {
        const el = trackRef.current
        if (!el) return
        const prevent = (e: Event) => e.preventDefault()
        el.addEventListener("touchmove", prevent, { passive: false })
        return () => el.removeEventListener("touchmove", prevent)
    }, [])

    const set = (p: number) => {
        progressRef.current = p
        setProgress(p)
    }

    const handleLeft = TRACK_PAD + usable * progress
    // Signed overshoot past either end (0 while inside the track) - drives the
    // rubber-band stretch.
    const overshoot = progress < 0 ? progress : progress > 1 ? progress - 1 : 0
    const handleCenter = handleLeft + HANDLE_W / 2
    const swept = (i: number) => handleCenter >= waypointX(i, trackW)

    // Rests on the total ($4.78) and counts DOWN as dust is swept, reaching
    // $0.00 when everything is collected (dust remaining).
    const collected = TOKENS.reduce(
        (sum, t, i) => (swept(i) ? sum + t.value : sum),
        0
    )
    const remaining = Math.max(0, TOTAL - collected)
    const priceValue = loaded ? remaining : 0

    // How many tokens are currently swept - drives the slider's ARIA value.
    const sweptCount = TOKENS.reduce((n, _t, i) => (swept(i) ? n + 1 : n), 0)

    // Start the SOL roll as soon as the reel can animate it - see
    // SOL_ROLL_MAX_WAIT. Polling a frame at a time keeps the spun figure on
    // screen for the shortest possible moment, so it reads as a number already
    // in motion rather than as the amount received.
    useEffect(() => {
        if (!complete) {
            setSolRoll(false)
            return
        }
        let raf = 0
        const startedAt = performance.now()
        const tick = () => {
            const ready = solHostRef.current?.querySelector("[data-rn-ready]")
            if (ready || performance.now() - startedAt > SOL_ROLL_MAX_WAIT) {
                // One more frame: ready means it has measured, not that it has painted.
                raf = requestAnimationFrame(() => setSolRoll(true))
                return
            }
            raf = requestAnimationFrame(tick)
        }
        raf = requestAnimationFrame(tick)
        return () => cancelAnimationFrame(raf)
    }, [complete])

    // Unclamped pointer position, in progress units. The track's rect is frozen
    // at grab time: the rubber-band stretch transforms the track, and measuring
    // the live (scaled) rect mid-drag would feed that back into the pointer math.
    const rawFromEvent = (e: React.PointerEvent) => {
        const rect =
            rectRef.current ||
            (rectRef.current = trackRef.current!.getBoundingClientRect())
        return (
            (e.clientX - rect.left - TRACK_PAD - HANDLE_W / 2) /
            usableFor(rect.width)
        )
    }
    // Rubber-band both ends: a dead zone of slack first, then stretch with
    // diminishing returns. The knob never leaves the track, it squashes instead.
    const withRubber = (raw: number) => {
        if (raw < 0) return -rubberBand(Math.max(0, -raw - RUBBER_DEAD))
        if (raw > 1) return 1 + rubberBand(Math.max(0, raw - 1 - RUBBER_DEAD))
        return raw
    }

    // Return to the start after releasing short of the goal. No momentum -
    // this is a fixed, decelerating tween from wherever the knob was let go,
    // so swipe speed never affects how far it travels.
    const returnHome = () => {
        cancelAnimationFrame(raf.current)
        const from = progressRef.current
        const start = performance.now()
        const easeOut = (t: number) => 1 - Math.pow(1 - t, 4) // decelerate into home
        const step = (now: number) => {
            const t = Math.min(1, (now - start) / HOME_MS)
            set(from * (1 - easeOut(t)))
            if (t < 1) raf.current = requestAnimationFrame(step)
            else set(0)
        }
        raf.current = requestAnimationFrame(step)
    }

    const onPointerDown = (e: React.PointerEvent) => {
        // Once swept, the bar becomes a "run it again" target: click to reset.
        if (complete) {
            e.preventDefault()
            reset()
            return
        }
        e.preventDefault() // no default focus/selection side effects on grab
        cancelAnimationFrame(raf.current)
        clearTimeout(loadTimer.current)
        setLoaded(true) // grabbing mid-reset shouldn't leave the price gated at $0.00
        dragging.current = true
        setActive(true) // fade the fill in
        e.currentTarget.setPointerCapture(e.pointerId)
        rectRef.current = trackRef.current!.getBoundingClientRect() // unscaled
        set(withRubber(rawFromEvent(e)))
    }
    const onPointerMove = (e: React.PointerEvent) => {
        if (!dragging.current || complete) return
        // No button held means the press already ended somewhere this element
        // never heard about - typically released off the canvas. Settle on where
        // the drag last was, rather than letting the knob follow a hover. A real
        // drag always has a button (or contact) down, so this cannot misfire.
        if (e.buttons === 0) {
            onPointerUp()
            return
        }
        set(withRubber(rawFromEvent(e))) // 1:1 with the finger, no acceleration
    }
    // Every way a drag can end lands here: pointerup, pointercancel, a lost
    // capture, or a buttonless move. The guard makes it safe to hit twice.
    const onPointerUp = () => {
        if (!dragging.current) return
        dragging.current = false
        rectRef.current = null
        // dragged to the end -> complete; otherwise ease back to start
        if (progressRef.current >= COMPLETE_AT) {
            finish()
            return
        }
        setActive(false) // fade the fill back out
        returnHome()
    }

    // One arrow press sweeps one token, so the keyboard path mirrors the
    // waypoints rather than moving by an arbitrary percentage.
    const KEY_STEP = 1 / TOKENS.length
    const onKeyDown = (e: React.KeyboardEvent) => {
        if (complete) {
            if (e.key === "Enter" || e.key === " ") {
                e.preventDefault()
                reset()
            }
            return
        }
        let next = progressRef.current
        switch (e.key) {
            case "ArrowRight":
            case "ArrowUp":
                next = Math.min(1, next + KEY_STEP)
                break
            case "ArrowLeft":
            case "ArrowDown":
                next = Math.max(0, next - KEY_STEP)
                break
            case "Home":
                next = 0
                break
            case "End":
            case "Enter":
            case " ":
                next = 1
                break
            default:
                return
        }
        e.preventDefault()
        cancelAnimationFrame(raf.current)
        clearTimeout(loadTimer.current)
        setLoaded(true)
        setActive(next > 0)
        if (next >= 1) finish()
        else set(next)
    }

    const reset = () => {
        setComplete(false)
        setActive(false)
        returnHome() // glide the knob back instead of snapping it to the start
        // Replay the load count-up once the knob has settled home, so the price
        // counts up from a resting $0.00 rather than mid-glide.
        setLoaded(false)
        clearTimeout(loadTimer.current)
        loadTimer.current = setTimeout(() => setLoaded(true), HOME_MS + 80)
    }

    return (
        <div
            style={{
                display: "flex",
                justifyContent: "center",
                // The card must take its width from its container, never from its
                // content. Without a definite width here this element is shrink-to-fit
                // and the wrapper's `width: 100%` resolves against nothing, so the card
                // ends up min-content sized - and since Aeonik's tabular figures carry
                // a ~0.8px spread, every counted-down digit resized the whole card
                // mid-swipe. minWidth lets it still go below the design width.
                width: "100%",
                maxWidth: CARD_W,
                minWidth: 0,
                fontFamily:
                    'Aeonik, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                ...style,
            }}
        >
            <style>{FONT_CSS + ROLLING_CSS + KEYFRAMES_CSS}</style>
            {/* iPhone mockup frame - border only, open at the bottom (cropped phone).
          SHOW_PHONE=false strips frame, bezel and status bar: card only. */}
            <div
                style={
                    SHOW_PHONE
                        ? {
                              width: CARD_W, // content = exactly the card; 10px padding = the bezel
                              padding: "0 10px 40px",
                              background: T.phoneScreen,
                              borderTop: `0.5px solid ${T.phoneBorder}`,
                              borderLeft: `0.5px solid ${T.phoneBorder}`,
                              borderRight: `0.5px solid ${T.phoneBorder}`,
                              borderBottom: "none",
                              borderRadius: "48px 48px 0 0",
                          }
                        : { width: "100%", maxWidth: CARD_W, minWidth: 0 }
                }
            >
                {/* Status bar - symmetric insets */}
                {SHOW_PHONE && (
                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            padding: "22px 36px 20px",
                        }}
                    >
                        <span
                            style={{
                                fontSize: 17,
                                fontWeight: 600,
                                color: T.text,
                                fontFamily:
                                    '-apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", sans-serif',
                            }}
                        >
                            09:41
                        </span>
                        <svg
                            width="74"
                            height="14"
                            viewBox="0 0 74 14"
                            fill="none"
                        >
                            {/* cellular - 4 pill bars, ascending (doubled gap) */}
                            <rect
                                x="0"
                                y="8.49"
                                width="3.2"
                                height="4.51"
                                rx="1.6"
                                fill={T.text}
                            />
                            <rect
                                x="5.22"
                                y="6.38"
                                width="3.2"
                                height="6.62"
                                rx="1.6"
                                fill={T.text}
                            />
                            <rect
                                x="10.44"
                                y="3.84"
                                width="3.2"
                                height="9.16"
                                rx="1.6"
                                fill={T.text}
                            />
                            <rect
                                x="15.66"
                                y="1.08"
                                width="3.2"
                                height="11.92"
                                rx="1.6"
                                fill={T.text}
                            />
                            {/* wifi - bold arcs + rounded upside-down triangle wedge */}
                            <path
                                d="M25.28 5.1c4.3-4 10.8-4 15.1 0"
                                stroke={T.text}
                                strokeWidth="2.7"
                                strokeLinecap="round"
                            />
                            <path
                                d="M28.28 8.35c2.6-2.4 6.5-2.4 9.1 0"
                                stroke={T.text}
                                strokeWidth="2.7"
                                strokeLinecap="round"
                            />
                            <path
                                d="M32.83 9.86 C34.16 9.86 34.84 10.47 34.84 11.09 C34.84 11.77 33.82 13.0 32.83 13.0 C31.84 13.0 30.82 11.77 30.82 11.09 C30.82 10.47 31.5 9.86 32.83 9.86 Z"
                                fill={T.text}
                            />
                            {/* battery - rounded body + side nub */}
                            <rect
                                x="46.81"
                                y="1.08"
                                width="24.28"
                                height="12.58"
                                rx="4.2"
                                fill={T.text}
                            />
                            <path
                                d="M72.11 5.37v3.71c1.15-.32 1.9-1.08 1.9-1.86s-.75-1.53-1.9-1.85z"
                                fill={T.text}
                            />
                        </svg>
                    </div>
                )}
                {/* Fixed-height holder: the card can shrink inside it on completion,
            but the holder (and so the phone frame) keeps its idle height.
            Extra height leaves grey below the card even at the completion peak
            (taller receipt + still-present band, before it collapses). */}
                <div style={{ height: SHOW_PHONE ? CARD_H + 50 : "auto" }}>
                    <div
                        style={{
                            width: "100%",
                            maxWidth: CARD_W,
                            height: "auto",
                            boxSizing: "border-box", // padding sits inside the width; 16px stays intact
                            background: T.card,
                            boxShadow: T.cardShadow,
                            borderRadius: CARD_R,
                            padding: CARD_PAD,
                            userSelect: "none",
                            WebkitUserSelect: "none",
                        }}
                    >
                        {/* Sheet grab handle */}
                        {SHOW_GRABBER && (
                            <div
                                style={{
                                    width: 35,
                                    height: 3,
                                    borderRadius: 999,
                                    background: T.grabber,
                                    margin: "-2px auto 8px",
                                }}
                            />
                        )}
                        {/* Title row - Aeonik Medium + claimable chip */}
                        <div
                            style={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "space-between",
                                gap: 12,
                                marginBottom: 15,
                            }}
                        >
                            <span
                                style={{
                                    fontSize: 24,
                                    fontWeight: 500,
                                    color: T.text,
                                }}
                            >
                                {title}
                            </span>
                            {/* Turns from "claimable" into "claimed" once the payoff lands. */}
                            <span
                                style={{
                                    flexShrink: 0,
                                    fontSize: 12,
                                    fontWeight: 500,
                                    lineHeight: 1,
                                    color: T.claimText,
                                    background: T.claimBg,
                                    borderRadius: 999,
                                    padding: "3px 8px",
                                    whiteSpace: "nowrap",
                                }}
                            >
                                ${TOTAL.toFixed(2)}{" "}
                                {/* Both words share one grid cell and cross-fade; the cell's
                width eases between their measured widths, clipping the
                outgoing word as it goes. */}
                                <span
                                    style={{
                                        display: "inline-grid",
                                        verticalAlign: "top",
                                        overflow: "hidden",
                                        width: wordW
                                            ? claimed
                                                ? wordW.claimed
                                                : wordW.claimable
                                            : "auto",
                                        transition: reduced
                                            ? "none"
                                            : `width 0.35s ${EASE}`,
                                    }}
                                >
                                    <span
                                        ref={claimableRef}
                                        aria-hidden={claimed}
                                        style={{
                                            gridArea: "1 / 1",
                                            justifySelf: "start",
                                            opacity: claimed ? 0 : 1,
                                            transition: `opacity 0.25s ${EASE}`,
                                        }}
                                    >
                                        claimable
                                    </span>
                                    <span
                                        ref={claimedRef}
                                        aria-hidden={!claimed}
                                        style={{
                                            gridArea: "1 / 1",
                                            justifySelf: "start",
                                            opacity: claimed ? 1 : 0,
                                            transition: `opacity 0.25s ${EASE}`,
                                        }}
                                    >
                                        claimed
                                    </span>
                                </span>
                            </span>
                        </div>

                        {/* Token list - 10px between rows. Dim to light grey once swept. */}
                        <div
                            style={{
                                display: "flex",
                                flexDirection: "column",
                                gap: 10,
                            }}
                        >
                            {TOKENS.map((t, i) => (
                                <div
                                    key={t.symbol}
                                    style={{
                                        display: "flex",
                                        justifyContent: "space-between",
                                        alignItems: "center",
                                        fontSize: 12,
                                        // same light grey whether mid-swipe or completed (no brighten jump)
                                        opacity: swept(i) ? T.rowSwept : 1,
                                        transition: `opacity 0.45s ${EASE}`,
                                    }}
                                >
                                    <span
                                        style={{
                                            display: "flex",
                                            alignItems: "center",
                                            gap: SHOW_ICONS ? 5 : 0,
                                            fontWeight: 400,
                                            color: T.text,
                                        }}
                                    >
                                        {SHOW_ICONS && (
                                            <img
                                                src={t.icon}
                                                alt=""
                                                width={15}
                                                height={15}
                                                style={{
                                                    width: 15,
                                                    height: 15,
                                                    borderRadius: "50%",
                                                    display: "block",
                                                    flexShrink: 0,
                                                }}
                                            />
                                        )}
                                        {t.amount} {t.symbol}
                                    </span>
                                    <span
                                        style={{
                                            fontWeight: 500,
                                            color: T.text,
                                        }}
                                    >
                                        ${t.value.toFixed(2)}
                                    </span>
                                </div>
                            ))}
                        </div>

                        {/* Divider */}
                        <div
                            style={{
                                borderTop: `1px dashed ${T.divider}`,
                                margin: "12px 0 16px",
                            }}
                        />

                        {/* Instruction/price  ->  confirmation. The active state is in flow
            (defines height); the other is absolute + faded. */}
                        <div style={{ position: "relative", marginBottom: 20 }}>
                            {/* PRE-COMPLETE: instruction (left) + dust price (right).
              grid 1fr->0fr collapses its height smoothly on completion. */}
                            <div
                                style={{
                                    display: "grid",
                                    gridTemplateRows: complete ? "0fr" : "1fr",
                                    opacity: complete ? 0 : 1,
                                    transition: `grid-template-rows 0.4s ${EASE}, opacity 0.28s ${EASE}`,
                                    pointerEvents: complete ? "none" : "auto",
                                }}
                                aria-hidden={complete}
                            >
                                <div
                                    style={{ overflow: "hidden", minHeight: 0 }}
                                >
                                    <div
                                        style={{
                                            display: "flex",
                                            justifyContent: "space-between",
                                            alignItems: "center",
                                            gap: 12,
                                            width: "100%",
                                        }}
                                    >
                                        <div
                                            style={{
                                                flex: 1,
                                                minWidth: 0, // without this the text refuses to wrap
                                                minHeight: 40,
                                                display: "flex",
                                                flexDirection: "column",
                                                justifyContent: "center",
                                                fontSize: 13,
                                                lineHeight: 1.45,
                                                color: T.text,
                                                fontWeight: 400,
                                            }}
                                        >
                                            <span>
                                                Dust will be converted to
                                                Solana.
                                            </span>
                                        </div>
                                        <span style={{ flexShrink: 0 }}>
                                            <RollingPrice
                                                value={priceValue}
                                                color={T.text}
                                                motionBlur={!reduced}
                                            />
                                        </span>
                                    </div>
                                </div>
                            </div>

                            {/* COMPLETE: receipt. grid 0fr->1fr expands its height smoothly so
              the content grows in instead of snapping. */}
                            <div
                                style={{
                                    display: "grid",
                                    gridTemplateRows: complete ? "1fr" : "0fr",
                                    transition: `grid-template-rows ${RECEIPT_OPEN_MS}ms ${EASE}`,
                                    pointerEvents: "none",
                                }}
                                aria-hidden={!complete}
                                role="status"
                            >
                                <div
                                    style={{ overflow: "hidden", minHeight: 0 }}
                                >
                                    <div
                                        style={{
                                            display: "flex",
                                            flexDirection: "column",
                                            gap: 10,
                                        }}
                                    >
                                        {/* You received -> the payoff, at the size the price had. The
                pre-complete block collapses as this one expands, so the card's
                hero number never moves; it only changes meaning, from what the
                dust was worth to what you got for it. */}
                                        <div
                                            style={{
                                                display: "flex",
                                                justifyContent: "space-between",
                                                alignItems: "center",
                                                gap: 12,
                                                fontSize: 14,
                                                color: T.text,
                                                opacity: complete ? 1 : 0,
                                                transition: `opacity 0.4s ${EASE} 0.09s`,
                                            }}
                                        >
                                            <span
                                                style={{
                                                    fontWeight: 400,
                                                    minWidth: 0,
                                                }}
                                            >
                                                You received (SOL)
                                            </span>
                                            <span
                                                ref={solHostRef}
                                                style={{ flexShrink: 0 }}
                                            >
                                                <RollingSolGain
                                                    value={
                                                        solRoll
                                                            ? SOL_VALUE
                                                            : spunFrom(
                                                                  solRollSpin
                                                              )
                                                    }
                                                    color={T.solText}
                                                    size={PRICE_SIZE}
                                                    suffix=""
                                                    shimmerColor={T.solShimmer}
                                                    shimmerBlend={
                                                        T.solShimmerBlend
                                                    }
                                                    motionBlur={!reduced}
                                                    rollMs={solRollMs}
                                                    stagger={solStagger}
                                                    shimmer={
                                                        solRoll && !reduced
                                                    }
                                                    shimmerMs={solShimmerMs}
                                                    shimmerFade={solShimmerFade}
                                                />
                                            </span>
                                        </div>

                                        {/* Confirmation, as a caption under the payoff it describes.
                Above it, it pushed the number a line below the slot the
                price had held. */}
                                        <div
                                            style={{
                                                display: "flex",
                                                alignItems: "center",
                                                gap: 10,
                                                opacity: complete ? 1 : 0,
                                                // Only once there is room for it - see RECEIPT_OPEN_MS.
                                                transition: complete
                                                    ? `opacity 0.3s ${EASE} ${RECEIPT_OPEN_MS}ms`
                                                    : `opacity 0.2s ${EASE}`,
                                            }}
                                        >
                                            <span
                                                style={{
                                                    width: 20,
                                                    height: 20,
                                                    borderRadius: "50%",
                                                    background: checkColor,
                                                    display: "inline-flex",
                                                    alignItems: "center",
                                                    justifyContent: "center",
                                                    flexShrink: 0,
                                                    // The overshoot lives here rather than on the line's swell,
                                                    // so the mark snaps without the sentence moving further.
                                                    animation:
                                                        complete && !reduced
                                                            ? `checkPop 0.4s ${POP} ${RECEIPT_OPEN_MS + 60}ms both`
                                                            : "none",
                                                }}
                                            >
                                                <svg
                                                    width="11"
                                                    height="11"
                                                    viewBox="0 0 12 12"
                                                    fill="none"
                                                    aria-hidden="true"
                                                >
                                                    <path
                                                        d="M2.5 6.5L5 9L9.5 3.5"
                                                        stroke="#fff"
                                                        strokeWidth="1.8"
                                                        strokeLinecap="round"
                                                        strokeLinejoin="round"
                                                        strokeDasharray={11}
                                                        style={{
                                                            // Undrawn only while it is drawing; with no animation the
                                                            // offset stays 0, so the tick is simply there.
                                                            animation:
                                                                complete &&
                                                                !reduced
                                                                    ? `checkDraw 0.3s ${EASE} ${RECEIPT_OPEN_MS + 240}ms both`
                                                                    : "none",
                                                        }}
                                                    />
                                                </svg>
                                            </span>
                                            <span
                                                style={{
                                                    fontSize: 14,
                                                    fontWeight: 500,
                                                    color: T.text,
                                                }}
                                            >
                                                {TOKENS.length} tokens have been
                                                successfully swept.
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Slider track */}
                        <div
                            ref={trackRef}
                            className="cdc-track"
                            role="slider"
                            tabIndex={0}
                            aria-label={
                                complete
                                    ? "Sweep again"
                                    : "Swipe to remove dust"
                            }
                            aria-valuemin={0}
                            aria-valuemax={TOKENS.length}
                            aria-valuenow={sweptCount}
                            aria-valuetext={
                                complete
                                    ? `All ${TOKENS.length} tokens swept. Press Enter to run it again.`
                                    : `${sweptCount} of ${TOKENS.length} tokens swept, $${remaining.toFixed(
                                          2
                                      )} of dust left`
                            }
                            onKeyDown={onKeyDown}
                            onPointerDown={onPointerDown}
                            onPointerMove={onPointerMove}
                            onPointerUp={onPointerUp}
                            onPointerCancel={onPointerUp}
                            // Capture can be taken away without a pointerup ever arriving -
                            // leaving the frame mid-drag is the common one. Treat it as release.
                            onLostPointerCapture={onPointerUp}
                            style={{
                                position: "relative",
                                width: "100%",
                                height: TRACK_H,
                                borderRadius: TRACK_R,
                                background: T.track,
                                overflow: "hidden",
                                touchAction: "none",
                                cursor: complete ? "pointer" : "grab", // pointer = click to reset
                                // Rubber band: the track stretches in the overflow direction,
                                // anchored at the opposite edge, so pulling past an end is felt.
                                transformOrigin:
                                    overshoot < 0
                                        ? "right center"
                                        : "left center",
                                transform: `scaleX(${1 + Math.abs(overshoot) * STRETCH})`,
                                transition: dragging.current
                                    ? "none"
                                    : `transform 0.45s ${EASE}`, // snaps back on release
                            }}
                        >
                            {/* Hint text - a constant shimmer travels through it; fades out
              once the user grabs the handle. */}
                            <div
                                style={{
                                    position: "absolute",
                                    inset: 0,
                                    display: "flex",
                                    alignItems: "center",
                                    justifyContent: "center",
                                    fontSize: 15,
                                    fontWeight: 400,
                                    letterSpacing: "0.01em",
                                    whiteSpace: "nowrap",
                                    backgroundImage: `linear-gradient(90deg, ${T.hint} 0%, ${T.hint} 10%, ${hintTint(
                                        fillMid
                                    )} 34%, ${hintTint(fillEnd)} 50%, ${hintTint(
                                        fillMid
                                    )} 66%, ${T.hint} 90%, ${T.hint} 100%)`,
                                    backgroundSize: "180px 100%",
                                    backgroundRepeat: "repeat",
                                    WebkitBackgroundClip: "text",
                                    backgroundClip: "text",
                                    color: "transparent",
                                    animation: reduced
                                        ? "none"
                                        : `hintShimmer 1.9s linear infinite`,
                                    opacity: Math.max(
                                        0,
                                        1 - Math.max(0, progress) / 0.25
                                    ),
                                    transition: `opacity 0.15s ${EASE}`,
                                    pointerEvents: "none",
                                    zIndex: 1,
                                }}
                            >
                                Swipe to remove dust
                            </div>
                            {/* Gradient fill, clipped - gradient stays fixed to the track */}
                            <div
                                style={{
                                    position: "absolute",
                                    top: 0,
                                    left: 0,
                                    bottom: 0,
                                    width: Math.min(
                                        trackW,
                                        handleLeft + HANDLE_W + TRACK_PAD
                                    ), // fill wraps around the handle
                                    overflow: "hidden",
                                    borderRadius: TRACK_R,
                                    opacity: active ? 1 : 0, // only fades in while the handle is held
                                    transition: `opacity 0.25s ${EASE}`,
                                }}
                            >
                                <div
                                    style={{
                                        position: "absolute",
                                        top: -10,
                                        left: -gradLead(trackW),
                                        width: gradSpan(trackW) + FILL_BLEED,
                                        height: "calc(100% + 20px)", // overshoot top/bottom so the blur's soft edges get clipped
                                        // Stops land at their true track percentages; the bleed either
                                        // side keeps the blur's soft edge outside the visible track.
                                        background: fillGradient(
                                            T.card,
                                            fillMid,
                                            fillEnd,
                                            gradientMidAt,
                                            gradientEndAt,
                                            trackW
                                        ),
                                        filter: `blur(${gradientBlur}px)`,
                                    }}
                                />
                                {/* Completion flourish. It lives inside the fill, so the fill's
                overflow and radius clip it to the bar, and it fades out with
                the fill on reset. Each variant rests somewhere invisible, so
                removing the animation never flashes it on screen. */}
                                {completionFlourish !== "none" && !reduced && (
                                    <div
                                        aria-hidden="true"
                                        style={{
                                            position: "absolute",
                                            top: 0,
                                            bottom: 0,
                                            pointerEvents: "none",
                                            opacity: complete ? 1 : 0,
                                            transition: complete
                                                ? "none"
                                                : `opacity 0.25s ${EASE}`,
                                            ...(completionFlourish === "shine"
                                                ? {
                                                      left: 0,
                                                      width: "45%",
                                                      // Taller than the bar by twice the blur, so the blur's
                                                      // soft top and bottom fall outside the clip and the
                                                      // streak stays full height; only its sides diffuse.
                                                      top: -shineBlur * 2,
                                                      bottom: -shineBlur * 2,
                                                      filter:
                                                          shineBlur > 0
                                                              ? `blur(${shineBlur}px)`
                                                              : undefined,
                                                      background:
                                                          "linear-gradient(100deg, transparent 0%, rgba(255, 255, 255, 0.6) 50%, transparent 100%)",
                                                      transform:
                                                          "translateX(220%)", // at rest: off the right edge
                                                      animation: complete
                                                          ? `fillShine ${flourishMs}ms ${EASE} both`
                                                          : "none",
                                                  }
                                                : completionFlourish === "flood"
                                                  ? {
                                                        left: -FLOOD_EDGE,
                                                        width: `calc(100% + ${FLOOD_EDGE}px)`,
                                                        background: `linear-gradient(90deg, transparent 0px, ${fillEnd} ${FLOOD_EDGE}px, ${fillEnd} 100%)`,
                                                        transform:
                                                            "translateX(0%)", // holds covering the bar
                                                        animation: complete
                                                            ? `fillFlood ${flourishMs}ms ${EASE} both`
                                                            : "none",
                                                    }
                                                  : {
                                                        left: 0,
                                                        right: 0,
                                                        background:
                                                            "radial-gradient(ellipse 70% 140% at 100% 50%, rgba(255, 255, 255, 0.55), transparent 70%)",
                                                        mixBlendMode: "screen",
                                                        animation: complete
                                                            ? `fillPulse ${flourishMs}ms ${EASE} both`
                                                            : "none",
                                                    }),
                                        }}
                                    />
                                )}
                            </div>
                            {/* Handle - overshoot past either edge shows as a squash, so the
              rubber-band stays visible inside the clipped track */}
                            <div
                                style={{
                                    position: "absolute",
                                    top: (TRACK_H - HANDLE_H) / 2,
                                    left: Math.min(
                                        TRACK_PAD + usable,
                                        Math.max(TRACK_PAD, handleLeft)
                                    ),
                                    width: HANDLE_W,
                                    height: HANDLE_H,
                                    // A plain capsule throughout: half the width, so it stays a
                                    // true capsule if HANDLE_W ever changes.
                                    borderRadius: HANDLE_W / 2,
                                    background: T.handle,
                                    boxShadow: active ? "none" : T.handleShadow,
                                    transition: `box-shadow 0.25s ${EASE}`, // follows the fill's fade
                                    transformOrigin:
                                        progress > 1
                                            ? "right center"
                                            : "left center",
                                    transform:
                                        progress < 0
                                            ? `scaleX(${Math.max(0.55, 1 + progress * 1.4)})`
                                            : progress > 1
                                              ? `scaleX(${Math.max(0.55, 1 - (progress - 1) * 1.4)})`
                                              : "scaleX(1)",
                                    cursor: complete ? "pointer" : "grab",
                                    zIndex: 2,
                                }}
                            />
                        </div>

                        {/* Waypoints - collapse the now-empty band once swept clean.
            grid-template-rows 1fr->0fr animates height smoothly; the card's
            auto height follows it down while keeping its 16px padding. */}
                        <div
                            style={{
                                display: "grid",
                                gridTemplateRows: complete ? "0fr" : "1fr",
                                transition: `grid-template-rows 0.5s ${EASE} ${complete ? "0.5s" : "0s"}`,
                            }}
                            aria-hidden={complete}
                        >
                            <div style={{ overflow: "visible", minHeight: 0 }}>
                                <div
                                    style={{
                                        position: "relative",
                                        width: "100%",
                                        height: WAYPOINT_ROW_H,
                                        marginTop: 10,
                                    }}
                                >
                                    {TOKENS.map((t, i) => (
                                        <div
                                            key={t.symbol}
                                            style={
                                                {
                                                    position: "absolute",
                                                    left: waypointX(i, trackW),
                                                    top: 0,
                                                    transform:
                                                        "translateX(-50%)",
                                                    // during drag: settle-poof to faded. on completion: fully
                                                    // dissolve while the dust motes scatter away.
                                                    opacity: complete
                                                        ? 0
                                                        : swept(i)
                                                          ? T.labelSwept
                                                          : 1,
                                                    "--label-swept":
                                                        T.labelSwept,
                                                    // Both of these blur and scale, so under reduced motion
                                                    // the opacity change above carries the state on its own.
                                                    animation: reduced
                                                        ? "none"
                                                        : complete
                                                          ? `labelDissolve 0.4s ${EASE} forwards`
                                                          : swept(i)
                                                            ? `poofSettle 0.55s ${EASE}`
                                                            : "none",
                                                    transition: `opacity 0.3s ${EASE}`,
                                                    display: "flex",
                                                    flexDirection: "column",
                                                    alignItems: "center",
                                                    gap: WAYPOINT_GAP,
                                                } as React.CSSProperties
                                            }
                                        >
                                            <span
                                                style={{
                                                    width: WAYPOINT_DOT,
                                                    height: WAYPOINT_DOT,
                                                    borderRadius: "50%",
                                                    background: T.label,
                                                }}
                                            />
                                            <span
                                                style={{
                                                    fontSize: 11,
                                                    lineHeight: `${WAYPOINT_LINE}px`,
                                                    fontWeight: 400,
                                                    letterSpacing: "0.02em",
                                                    color: T.label,
                                                }}
                                            >
                                                {t.symbol}
                                            </span>
                                        </div>
                                    ))}
                                    {/* Dust bursts on their own layer so the label's blur/dissolve
                  can't clip or blur the motes.

                  Each one fires as its own waypoint is crossed, not all at
                  once on completion - the row dimming and the label's poof
                  are already per-token, so the particles were the
                  only part of the sweep that ignored the gesture causing it.
                  Dragging back un-sweeps and re-arms them, the same way the
                  label's poof already re-triggers. */}
                                    {TOKENS.map((t, i) => (
                                        <DustBurst
                                            key={"burst-" + t.symbol}
                                            go={swept(i) && !reduced}
                                            seed={i}
                                            x={waypointX(i, trackW)}
                                            color={dustColor}
                                            count={dustCount}
                                            sizeScale={dustSize}
                                            spread={dustSpread}
                                            durationMs={dustMs}
                                            opacityScale={dustOpacity}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

addPropertyControls(ConvertDustCard, {
    title: {
        type: ControlType.String,
        title: "Title",
        defaultValue: "Clean dust",
    },
    dark: {
        type: ControlType.Boolean,
        title: "Theme",
        enabledTitle: "Dark",
        disabledTitle: "Light",
        defaultValue: true,
    },
    showGrabber: {
        type: ControlType.Boolean,
        title: "Grabber",
        defaultValue: true,
    },
    showIcons: {
        type: ControlType.Boolean,
        title: "Token icons",
        defaultValue: false,
    },
    // Only the active theme's pair is shown.
    gradientMid: {
        type: ControlType.Color,
        title: "Fill mid",
        defaultValue: GRAD_MID,
        hidden: (props: ConvertDustCardProps) => props.dark === false,
    },
    gradientEnd: {
        type: ControlType.Color,
        title: "Fill end",
        defaultValue: GRAD_END,
        hidden: (props: ConvertDustCardProps) => props.dark === false,
    },
    gradientMidLight: {
        type: ControlType.Color,
        title: "Fill mid",
        defaultValue: GRAD_MID_LIGHT,
        hidden: (props: ConvertDustCardProps) => props.dark !== false,
    },
    gradientEndLight: {
        type: ControlType.Color,
        title: "Fill end",
        defaultValue: GRAD_END_LIGHT,
        hidden: (props: ConvertDustCardProps) => props.dark !== false,
    },
    gradientMidAt: {
        type: ControlType.Number,
        title: "Mid at",
        defaultValue: GRAD_MID_AT,
        min: 0,
        max: 1,
        step: 0.01,
    },
    gradientEndAt: {
        type: ControlType.Number,
        title: "End at",
        defaultValue: GRAD_END_AT,
        min: 0,
        max: 1,
        step: 0.01,
    },
    gradientBlur: {
        type: ControlType.Number,
        title: "Fill blur",
        defaultValue: GRAD_BLUR,
        min: 0,
        max: 30,
        step: 1,
    },
    checkColor: {
        type: ControlType.Color,
        title: "Checkmark",
        defaultValue: GREEN,
    },
    solRollMs: {
        type: ControlType.Number,
        title: "SOL roll ms",
        defaultValue: SOL_ROLL_MS,
        min: 200,
        max: 4000,
        step: 100,
    },
    solRollSpin: {
        type: ControlType.Number,
        title: "SOL spin",
        defaultValue: SOL_SPIN,
        min: 1,
        max: 9,
        step: 1,
    },
    completionFlourish: {
        type: ControlType.Enum,
        title: "Flourish",
        defaultValue: FLOURISH,
        options: ["shine", "flood", "pulse", "none"],
        optionTitles: ["Shine", "Gold flood", "Pulse", "None"],
    },
    flourishMs: {
        type: ControlType.Number,
        title: "Flourish ms",
        defaultValue: FLOURISH_MS,
        min: 200,
        max: 2000,
        step: 50,
    },
    shineBlur: {
        type: ControlType.Number,
        title: "Shine blur",
        defaultValue: SHINE_BLUR,
        min: 0,
        max: 40,
        step: 1,
    },
    solStagger: {
        type: ControlType.Enum,
        title: "SOL stagger",
        defaultValue: SOL_STAGGER,
        options: ["start", "end", "outward", "none"],
        optionTitles: ["Left to right", "Right to left", "Outward", "Together"],
    },
    solShimmerMs: {
        type: ControlType.Number,
        title: "Shimmer ms",
        defaultValue: SOL_SHIMMER_MS,
        min: 400,
        max: 6000,
        step: 100,
    },
    solShimmerFade: {
        type: ControlType.Number,
        title: "Shimmer fade",
        defaultValue: SOL_SHIMMER_FADE,
        min: 0,
        max: 1,
        step: 0.05,
    },
    hintFade: {
        type: ControlType.Number,
        title: "Hint shimmer",
        defaultValue: HINT_FADE,
        min: 0,
        max: 1,
        step: 0.05,
    },
    dustColor: {
        type: ControlType.Color,
        title: "Dust",
        defaultValue: DUST_COLOR,
    },
    dustCount: {
        type: ControlType.Number,
        title: "Dust count",
        defaultValue: MOTES,
        min: 0,
        max: 120,
        step: 1,
    },
    dustSize: {
        type: ControlType.Number,
        title: "Dust size",
        defaultValue: DUST_SIZE,
        min: 0.2,
        max: 4,
        step: 0.1,
    },
    dustSpread: {
        type: ControlType.Number,
        title: "Dust spread",
        defaultValue: DUST_SPREAD,
        min: 0.2,
        max: 3,
        step: 0.1,
    },
    dustMs: {
        type: ControlType.Number,
        title: "Dust time",
        defaultValue: DUST_MS,
        min: 200,
        max: 4000,
        step: 100,
    },
    dustOpacity: {
        type: ControlType.Number,
        title: "Dust opacity",
        defaultValue: DUST_OPACITY,
        min: 0,
        max: 1.5,
        step: 0.05,
    },
})
